function check(input, actual, expected) {
  const [n, roads, names, targetPath] = input;
  if (!Array.isArray(actual) || actual.length !== targetPath.length) return false;
  if (actual.some(city => !Number.isInteger(city) || city < 0 || city >= n)) return false;
  const road = new Set(roads.map(([a, b]) => `${Math.min(a, b)},${Math.max(a, b)}`));
  for (let i = 1; i < actual.length; i++) {
    if (!road.has(`${Math.min(actual[i - 1], actual[i])},${Math.max(actual[i - 1], actual[i])}`)) return false;
  }
  const distance = walk => walk.reduce((sum, city, i) => sum + (names[city] === targetPath[i] ? 0 : 1), 0);
  return distance(actual) === distance(expected);
}

