function validate([n, roads, names, targetPath]) {
  if (!Number.isInteger(n) || n < 2 || n > 100) return 'n is between 2 and 100.';
  if (!Array.isArray(roads) || roads.length < n - 1 || roads.length > n * (n - 1) / 2) return 'roads needs between n - 1 and n(n - 1)/2 roads.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  const seen = new Set();
  let parts = n;
  for (const road of roads) {
    if (!Array.isArray(road) || road.length !== 2) return 'Each road joins exactly two cities.';
    const [a, b] = road;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Cities are numbered 0 to n - 1.';
    if (a === b) return 'A road joins two different cities.';
    const key = `${Math.min(a, b)},${Math.max(a, b)}`;
    if (seen.has(key)) return 'Two cities share at most one road.';
    seen.add(key);
    const ra = find(a), rb = find(b);
    if (ra !== rb) { parent[ra] = rb; parts--; }
  }
  if (parts !== 1) return 'The road network must be connected.';
  const code = /^[A-Z]{3}$/;
  if (!Array.isArray(names) || names.length !== n) return 'names needs one name per city.';
  if (names.some(name => typeof name !== 'string' || !code.test(name))) return 'Each name is three upper-case letters.';
  if (!Array.isArray(targetPath) || targetPath.length < 1 || targetPath.length > 100) return 'targetPath needs 1 to 100 names.';
  if (targetPath.some(name => typeof name !== 'string' || !code.test(name))) return 'Each targetPath entry is three upper-case letters.';
  return null;
}

