function mostSimilar(n, roads, names, targetPath) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of roads) {
    graph[a].push(b);
    graph[b].push(a);
  }
  const len = targetPath.length;
  const dp = Array.from({ length: len }, () => new Array(n).fill(Infinity));
  const prev = Array.from({ length: len }, () => new Array(n).fill(-1));

  for (let city = 0; city < n; city++) {
    dp[0][city] = names[city] === targetPath[0] ? 0 : 1;
  }
  for (let i = 1; i < len; i++) {
    for (let city = 0; city < n; city++) {
      const cost = names[city] === targetPath[i] ? 0 : 1;
      for (const neighbor of graph[city]) {
        if (dp[i - 1][neighbor] + cost < dp[i][city]) {
          dp[i][city] = dp[i - 1][neighbor] + cost;
          prev[i][city] = neighbor;
        }
      }
    }
  }

  let last = 0;
  for (let city = 1; city < n; city++) {
    if (dp[len - 1][city] < dp[len - 1][last]) {
      last = city;
    }
  }
  const path = new Array(len);
  for (let i = len - 1; i >= 0; i--) {
    path[i] = last;
    last = prev[i][last];
  }
  return path;
}

