function mostSimilar(n, roads, names, targetPath) {
  // Try every walk of the right length depth-first, pruning walks already no better than the best found.
  const adjacent = Array.from({ length: n }, () => new Array(n).fill(false));
  for (const [a, b] of roads) adjacent[a][b] = adjacent[b][a] = true;
  let best = null, bestCost = Infinity;
  const walk = [];
  const extend = cost => {
    if (cost >= bestCost) return;
    if (walk.length === targetPath.length) { best = walk.slice(); bestCost = cost; return; }
    for (let city = 0; city < n; city++) {
      if (walk.length > 0 && !adjacent[walk[walk.length - 1]][city]) continue;
      const miss = names[city] !== targetPath[walk.length] ? 1 : 0;
      walk.push(city);
      extend(cost + miss);
      walk.pop();
    }
  };
  extend(0);
  return best;
}

