function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 100 : int(2, 5);
  const maxEdges = n * (n - 1) / 2;
  const edgeCount = large ? int(99, 2000) : int(n - 1, maxEdges);
  // A random spanning tree keeps the network connected; extra roads are added on top.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  const keys = new Set(), roads = [];
  const add = (a, b) => {
    const key = Math.min(a, b) * 1000 + Math.max(a, b);
    if (a === b || keys.has(key)) return;
    keys.add(key);
    roads.push(rand() < 0.5 ? [a, b] : [b, a]);
  };
  for (let i = 1; i < n; i++) add(order[i], order[int(0, i - 1)]);
  while (roads.length < edgeCount) add(int(0, n - 1), int(0, n - 1));
  for (let i = roads.length - 1; i > 0; i--) { const j = int(0, i); [roads[i], roads[j]] = [roads[j], roads[i]]; }
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const code = () => letters[int(0, 25)] + letters[int(0, 25)] + letters[int(0, 25)];
  const pool = large ? Array.from({ length: 30 }, code) : ['ATL', 'PEK', 'LAX', 'DXB', 'HND'].slice(0, int(1, 5));
  const names = Array.from({ length: n }, () => pool[int(0, pool.length - 1)]);
  // The target follows a real walk, then some of its names are replaced so the best walk must compromise.
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of roads) { graph[a].push(b); graph[b].push(a); }
  const len = large ? int(80, 100) : int(1, 6);
  const noise = rand();
  let city = int(0, n - 1);
  const targetPath = [];
  for (let i = 0; i < len; i++) {
    targetPath.push(rand() < noise ? (rand() < 0.5 ? code() : pool[int(0, pool.length - 1)]) : names[city]);
    city = graph[city][int(0, graph[city].length - 1)];
  }
  return [n, roads, names, targetPath];
}
